css:
.dcx *{ box-sizing: border-box; }
.dcx{ margin: 0; background: #F5F7F3; }
.dcx a{ color: #0B6B3F; text-decoration: none; }
.dcx a:hover{ color: #16A85F; }
.dcx :focus-visible{ outline: 2px solid #16A85F; outline-offset: 3px; }
.dcx [data-mega]{ display: none; }
.dcx [data-navitem]:hover [data-mega],.dcx [data-mega]:hover{ display: block; }
.dcx [data-burger]{ display: none; }
@media (max-width: 1180px){.dcx [data-navlinks],.dcx [data-navlogin]{ display: none !important; }
.dcx [data-burger]{ display: inline-flex !important; }
.dcx [data-hero]{ grid-template-columns: minmax(0,1fr) !important; }
.dcx [data-herocards]{ grid-template-columns: repeat(2, minmax(0,1fr)) !important; }
.dcx [data-plat]{ grid-template-columns: repeat(4, minmax(0,1fr)) !important; }
.dcx [data-plat] > li{ border-left: 0 !important; }
.dcx [data-feat]{ grid-template-columns: minmax(0,1fr) !important; }
.dcx [data-feat6]{ grid-template-columns: repeat(2, minmax(0,1fr)) !important; }
.dcx [data-results]{ grid-template-columns: minmax(0,1fr) !important; }
.dcx [data-steps]{ grid-template-columns: repeat(2, minmax(0,1fr)) !important; }
.dcx [data-steps] > div > svg{ display: none !important; }
.dcx [data-stepsrow]{ grid-template-columns: minmax(0,1fr) !important; }
.dcx [data-widgets]{ grid-template-columns: minmax(0,1fr) !important; }
.dcx [data-widgets3]{ grid-template-columns: repeat(3, minmax(0,1fr)) !important; }
.dcx [data-cta]{ grid-template-columns: minmax(0,1fr) !important; }
.dcx [data-script]{ display: none !important; }
}
@media (max-width: 720px){.dcx [data-pad]{ padding-left: 18px !important; padding-right: 18px !important; }
.dcx [data-herocards],.dcx [data-plat],.dcx [data-feat6],.dcx [data-kpis],.dcx [data-steps],.dcx [data-widgets3]{ grid-template-columns: minmax(0,1fr) !important; }
.dcx [data-h1]{ font-size: 34px !important; }
.dcx [data-h2]{ font-size: 22px !important; }
.dcx [data-pad]{ padding-top: 24px !important; }
}
